/* ── browser storage: every access guarded (private mode, blocked storage) ── */
var K_PLAYS = 'mh_d11_plays', K_BEST = 'mh_d11_best', K_SAVED = 'mh_d11_saved', K_EMAIL = 'mh_d11_email';
function lsGet(k, d){ try { var v = localStorage.getItem(k); return v == null ? d : JSON.parse(v); } catch(e){ return d; } }
function lsSet(k, v){ try { localStorage.setItem(k, JSON.stringify(v)); } catch(e){} }

var score=0,timeLeft=15,mode='ready',endAt=0,startedAt=0,ticker=null,productIndex=0,combo=0,lastTap=0,best=Number(lsGet(K_BEST,0))||0,audioCtx=null,soundEnabled=false,currentItem=goodProducts[0],nextSwapAt=0,goodsSinceBad=0,badShown=0,goodTaps=0,badTaps=0,tapLog=[],round=null,saving=false,badShownAt=0,holdUntil=0,badDueAt=0,hitEl=null,warnOn=false,maxCombo=0,badSinceTap=false;
var tapLabel=$('tapButton').querySelector('span'),badge=$('featureProduct').querySelector('.badge-plus');

function clampScore(v){return Math.max(0,v)}
function randomFrom(arr){return arr[Math.floor(Math.random()*arr.length)]}
function playsUsed(){ return Number(lsGet(K_PLAYS, 0)) || 0; }
function playsLeft(){ return CFG.MAX_PLAYS ? Math.max(0, CFG.MAX_PLAYS - playsUsed()) : Infinity; }   // 0 = unlimited
function rand(r){ return r[0] + Math.random() * (r[1] - r[0]); }

function showOnly(id){
  ['startOverlay','endOverlay','savedOverlay','limitOverlay'].forEach(function(o){ $(o).hidden = (o !== id); });
}

function setFeature(item){
  var wasBad=!!currentItem.bad;
  currentItem=item;
  $('featureUse').setAttribute('href','#p-'+item.id);
  $('productLabel').textContent=item.name;
  var bad=!!item.bad;
  $('featureProduct').classList.toggle('bad',bad);$('shopStage').classList.toggle('bad-active',bad);if(bad){badShown++;goodsSinceBad=0;$('screen').querySelectorAll('.fly,.float-score').forEach(function(el){el.remove()});}
  $('productLabel').classList.toggle('bad',bad);
  badge.classList.toggle('bad',bad);
  badge.textContent=bad?'-'+CFG.BAD_PENALTY:'+1';                 // brief: −3 (V3 '-1')
  $('tapButton').classList.toggle('danger',bad);
  tapLabel.textContent=bad?'爛貨！唔好加購！':'加入購物車！';       // terms: 爛貨 / 搶手貨 (Marketing 2026-10-23)
  var ids=[1,3,8,5];
  for(var i=0;i<4;i++){$('float'+(i+1)).querySelector('use').setAttribute('href','#p-'+goodProducts[(productIndex+ids[i])%goodProducts.length].id)}
  if(mode!=='playing')return;
  var now=performance.now();
  if(bad){badShownAt=now;badSinceTap=true;restartClass($('screen'),'d11-bad-flash')}
  else if(wasBad)badDueAt=now+rand(CFG.BAD_GAP);              // next 爛貨 counts from when this one left
  lockState=null;updateLock(now);                                 // force: label + lock follow the new item at once
}
function restartClass(el,c){el.classList.remove(c);void el.offsetWidth;el.classList.add(c)}
/* the "誤按爛貨！−3分" stamp, created once inside the item area */
function hitStamp(show){
  if(!hitEl){hitEl=document.createElement('div');hitEl.className='d11-hit';hitEl.setAttribute('aria-hidden','true');hitEl.innerHTML='<b>誤按爛貨！</b><span>−'+CFG.BAD_PENALTY+'分</span>';$('shopStage').append(hitEl)}
  hitEl.classList.toggle('show',!!show);
}
function updateScoreUI(){
  $('score').textContent=score;
  $('cartCount').textContent=score+'分';
  $('progressFill').style.width=Math.min(100,Math.round(score/CFG.FULL_AT*100))+'%';
  $('cartMessage').textContent=score<5?'小心加購，慢慢儲分！':score<12?'開始上手喇！':score<CFG.FULL_AT?'購物車愈嚟愈滿！':'爆滿！繼續衝高分！';
  $('cartZone').classList.toggle('full',score>=CFG.FULL_AT);
}
/* change: V3 removed one cart item per −1. With −3 the cart has to follow
   the score (brief: "cart fullness follows the score"), so trim to match. */
function syncCart(){
  var inner=$('cartInner'),keep=Math.min(score,slots.length);
  while(inner.children.length>keep)inner.lastElementChild.remove();
}
function reset(){
  score=0;timeLeft=15;combo=0;maxCombo=0;badSinceTap=false;lastTap=0;productIndex=0;currentItem=goodProducts[0];goodsSinceBad=0;badShown=0;goodTaps=0;badTaps=0;tapLog=[];holdUntil=0;badShownAt=0;hitStamp(false);$('screen').classList.remove('d11-shake','d11-bad-flash');
  $('time').textContent='15';$('cartInner').replaceChildren();$('combo').textContent='READY!';showOnly(null);
  $('bottomTip').textContent='見到搶手貨就撳，爛貨千祈唔好撳！';
  showWarn(false);
  updateScoreUI();
  setFeature(goodProducts[0]);
}
/* Keep the whole play area on screen (brief: timer, score, product and
   button visible without scrolling during play). */
function bringIntoView(){
  var r=$('screen').getBoundingClientRect(),vh=window.innerHeight||0;
  if(r.top>=0&&r.bottom<=vh)return;
  var top=r.top-Math.max(0,(vh-r.height)/2);
  try{window.scrollBy({top:top,behavior:'smooth'})}catch(e){window.scrollBy(0,top)}
}
function start(){
  if(ticker){clearInterval(ticker);ticker=null}
  if(playsLeft()<=0){showCodes('start');return}                // only when MAX_PLAYS is set
  lsSet(K_PLAYS,playsUsed()+1);
  round={play_no:playsUsed()};
  reset();mode='playing';$('tapButton').disabled=false;startedAt=performance.now();endAt=startedAt+CFG.ROUND_MS;nextSwapAt=startedAt+850;badDueAt=startedAt+rand(CFG.BAD_FIRST);ticker=setInterval(tick,60);tick();
  bringIntoView();
}
function scheduleNext(now){nextSwapAt=now+(currentItem.bad?CFG.BAD_MS:CFG.GOOD_MS)+Math.random()*(currentItem.bad?CFG.BAD_JITTER:CFG.GOOD_JITTER)}
/* products only: 爛貨 comes from the timed schedule in tick(), always after a warning */
function rotateProduct(){
  productIndex=(productIndex+1+Math.floor(Math.random()*2))%goodProducts.length;
  setFeature(goodProducts[productIndex]);
}
/* When taps don't count (rubbish grace, hit freeze), the button says so and looks locked
   (Clara, 2026-10-21: "pressed rubbish but it did not count"). Checked on every tick (60 ms). */
var lockState='';
function updateLock(now){
  var s=holdUntil?'hold':(currentItem.bad&&now-badShownAt<CFG.BAD_GRACE_MS?'grace':'');
  if(s===lockState)return;lockState=s;
  var b=$('tapButton');b.classList.toggle('d11-locked',!!s);b.setAttribute('aria-disabled',s?'true':'false');
  tapLabel.textContent=s==='hold'?'已扣'+CFG.BAD_PENALTY+'分':s==='grace'?'停！睇清楚先':(currentItem.bad?'爛貨！唔好加購！':'加入購物車！');
}
/* "留意爛貨出沒！" — on from WARN_MS before a scheduled 爛貨 until it appears */
function showWarn(on){if(on===warnOn)return;warnOn=on;var w=$('badWarn');if(w){w.classList.toggle('show',on)}}
function tick(){
  if(mode!=='playing')return;
  var now=performance.now();
  var remain=Math.max(0,endAt-now);
  var sec=Math.ceil(remain/1000);
  if(sec!==timeLeft){timeLeft=sec;$('time').textContent=String(sec).padStart(2,'0');if(sec<=5&&sec>0)$('bottomTip').textContent='最後 '+sec+' 秒！小心唔好買錯！'}
  updateLock(now);
  if(holdUntil){if(now>=holdUntil){holdUntil=0;hitStamp(false);rotateProduct();scheduleNext(now)}}   // end of a hit freeze
  else if(!currentItem.bad&&now>=badDueAt){showWarn(false);setFeature(randomFrom(badProducts));scheduleNext(now)}   // scheduled 爛貨
  else if(!currentItem.bad&&now>=badDueAt-CFG.WARN_MS&&badDueAt<endAt)showWarn(true);                         // warning ahead of it
  else if(now>=nextSwapAt){rotateProduct(!!currentItem.bad);scheduleNext(now)}
  if(remain<=0)finish();
}
function sound(type){
  if(!soundEnabled)return;
  try{audioCtx=audioCtx||new(window.AudioContext||window.webkitAudioContext)();var oscillator=audioCtx.createOscillator();var gain=audioCtx.createGain();oscillator.connect(gain);gain.connect(audioCtx.destination);oscillator.type=type==='bad'?'square':'sine';oscillator.frequency.setValueAtTime(type==='bad'?240:690,audioCtx.currentTime);oscillator.frequency.exponentialRampToValueAtTime(type==='bad'?150:980,audioCtx.currentTime+.07);gain.gain.setValueAtTime(.03,audioCtx.currentTime);gain.gain.exponentialRampToValueAtTime(.001,audioCtx.currentTime+.11);oscillator.start();oscillator.stop(audioCtx.currentTime+.12)}catch(e){}
}
function showBubble(text,bad){
  var screen=$('screen'),a=$('featureSvg').getBoundingClientRect(),s=screen.getBoundingClientRect();
  var scoreBubble=document.createElement('span');scoreBubble.className='float-score'+(bad?' bad-score':'');scoreBubble.textContent=text;scoreBubble.style.left=(a.left+a.width/2-s.left+18)+'px';scoreBubble.style.top=(a.top-s.top)+'px';screen.append(scoreBubble);setTimeout(function(){scoreBubble.remove()},700);
}
function pulseTapArea(){var feature=$('featureProduct');feature.classList.remove('bounce');void feature.offsetWidth;feature.classList.add('bounce')}
function animateCart(kind){var cart=$('cart');cart.classList.remove('jiggle');void cart.offsetWidth;cart.classList.add('jiggle');if(kind==='bad'){cart.style.filter='saturate(.8)';setTimeout(function(){cart.style.filter=''},180)}}
function tapCurrent(){
  if(mode!=='playing')return;
  var now=performance.now();
  if(now>=endAt){finish();return}                                // brief: stop accepting taps at 15 s
  var isBad=!!currentItem.bad;
  /* ignored taps are logged as 'i' (no score): during a hit freeze, or too soon after rubbish appeared */
  if(holdUntil||(isBad&&now-badShownAt<CFG.BAD_GRACE_MS)){tapLog.push('i'+Math.round(now-startedAt));return}
  tapLog.push((isBad?'b':'g')+Math.round(now-startedAt));       // change: tap log for score verification
  /* Combo = good taps in a row. A 爛貨 tap ends it. Waiting out a 爛貨 does NOT end it (Marketing
     2026-10-26): when a 爛貨 appeared since the last tap, the pause before the next good tap is forgiven.
     Otherwise a pause over 0.85 s restarts it. 最高Combo is a tie-breaker, so it is saved with the round. */
  if(isBad)combo=0;
  else combo=(now-lastTap<850||badSinceTap)&&lastTap?combo+1:1;
  badSinceTap=false;lastTap=now;if(combo>maxCombo)maxCombo=combo;
  $('combo').textContent=isBad?'扣'+CFG.BAD_PENALTY+'分！':(combo>=2?'COMBO ×'+combo:'＋1分！');   // no combo bonus points (brief)
  $('combo').classList.remove('pop');void $('combo').offsetWidth;$('combo').classList.add('pop');
  pulseTapArea();
  if(isBad){
    score=clampScore(score-CFG.BAD_PENALTY);badTaps++;updateScoreUI();syncCart();showBubble('-'+CFG.BAD_PENALTY,true);$('bottomTip').textContent='中伏！爛貨唔好亂撳呀！';animateCart('bad');sound('bad');
  }else{
    score++;goodTaps++;goodsSinceBad++;updateScoreUI();showBubble('+1');addCartVisual(currentItem,score);createFly(currentItem);$('bottomTip').textContent=score<10?'搶手貨即撳，爛貨要避開！':'Keep going！手速愈快，分數愈高！';animateCart('good');sound('good');
  }
  if(isBad){hitStamp(true);restartClass($('screen'),'d11-shake')}
  if(isBad&&CFG.RUBBISH_STAYS){setTimeout(function(){if(!holdUntil)hitStamp(false)},CFG.HIT_HOLD_MS);return}   // UAT option: rubbish keeps its interval
  if(isBad){holdUntil=now+CFG.HIT_HOLD_MS;updateLock(now);return}                // v4: the hit stays visible, then the next item
  rotateProduct(isBad);scheduleNext(now);
}
function addCartVisual(product,n){var inner=$('cartInner');var idx=Math.min(n-1,slots.length-1);if(n<=0)return;if(n<=slots.length){while(inner.children.length>=n)inner.lastElementChild.remove();var slot=slots[idx];var node=document.createElement('div');node.className='cart-item';node.style.left=slot[0]+'%';node.style.top=slot[1]+'px';node.style.setProperty('--rot',slot[2]+'deg');node.innerHTML='<svg viewBox="0 0 120 120" aria-hidden="true"><use href="#p-'+product.id+'"/></svg>';inner.append(node)}else if(n%4===0){var last=inner.lastElementChild;if(last)last.querySelector('use').setAttribute('href','#p-'+product.id)}}
function createFly(product){var screen=$('screen'),source=$('featureSvg'),dest=$('cart'),s=screen.getBoundingClientRect(),a=source.getBoundingClientRect(),b=dest.getBoundingClientRect();var node=document.createElement('div');node.className='fly';node.innerHTML='<svg viewBox="0 0 120 120"><use href="#p-'+product.id+'"/></svg>';node.style.left=(a.left+a.width/2-s.left-32)+'px';node.style.top=(a.top+a.height/2-s.top-32)+'px';screen.append(node);var dx=b.left+b.width/2-(a.left+a.width/2),dy=b.top+40-(a.top+a.height/2);if(node.animate){var anim=node.animate([{transform:'translate(0px,0px) scale(.9) rotate(-7deg)',opacity:1},{transform:'translate('+(dx*.55)+'px,'+(dy*.40-45)+'px) scale(.8) rotate(16deg)',opacity:1,offset:.55},{transform:'translate('+dx+'px,'+dy+'px) scale(.25) rotate(-20deg)',opacity:.15}],{duration:390,easing:'ease-in',fill:'forwards'});anim.onfinish=function(){node.remove()}}else setTimeout(function(){node.remove()},390);if(screen.querySelectorAll('.fly').length>16){var f=screen.querySelector('.fly');if(f)f.remove()}}

/* ── END OF ROUND → result + email (brief p2) ───────────────────── */
function finish(){
  if(mode!=='playing')return;mode='result';if(ticker){clearInterval(ticker);ticker=null}
  $('time').textContent='00';$('tapButton').disabled=true;showWarn(false);
  var newRecord=score>best;if(newRecord){best=score;lsSet(K_BEST,best)}
  round.score=score;round.good=goodTaps;round.bad=badTaps;round.max_combo=maxCombo;round.rubbish=badShown;round.log=tapLog.join(',');
  round.completed_at=new Date().toISOString();
  round.session_id=newSessionId();
  $('finalScore').textContent=score;$('finalBest').textContent=(newRecord?'新紀錄！':'個人最佳：')+best+'分';
  $('endTitle').textContent=endTitle(score,badTaps);
  $('endMessage').textContent='最高 Combo：'+maxCombo+' · 誤按爛貨：'+badTaps+' 次';
  resetForm();
  showOnly('endOverlay');
}
function endTitle(sc,hits){for(var i=0;i<CFG.TITLES.length;i++){var t=CFG.TITLES[i];if(sc>=t.min&&(t.maxHits==null||hits<=t.maxHits))return t.text}return CFG.TITLES[CFG.TITLES.length-1].text}
function home(){if(ticker){clearInterval(ticker);ticker=null}mode='ready';reset();$('tapButton').disabled=true;$('bottomTip').textContent='撳「即刻開始挑戰」開始遊戲！';showStart()}
function showStart(){
  if(playsLeft()<=0){showCodes('start');return}
  refreshCodeCount();
  showOnly('startOverlay');
}

/* ── IDs ──────────────────────────────────────────────────────────
   Result code: brief p2 "unique, non-guessable". 10 Crockford base-32
   characters from crypto.getRandomValues = 50 random bits. It is minted
   on the first submit and reused by every retry of the same round, and
   it is shown only once form.io has saved it (see saveRound). */
var B32='0123456789ABCDEFGHJKMNPQRSTVWXYZ';
function randBytes(n){var a=new Uint8Array(n);(window.crypto||window.msCrypto).getRandomValues(a);return a}
function newResultCode(){var b=randBytes(10),s='';for(var i=0;i<10;i++)s+=B32[b[i]&31];return 'D11-'+s.slice(0,5)+'-'+s.slice(5)}
function newSessionId(){if(window.crypto&&crypto.randomUUID)return crypto.randomUUID();var b=randBytes(16),h='';for(var i=0;i<16;i++)h+=(b[i]<16?'0':'')+b[i].toString(16);return h}

/* ── FORM ─────────────────────────────────────────────────────────── */
var EMAIL_RE=/^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/;
function resetForm(){
  saving=false;
  $('d11EmailErr').hidden=true;$('d11ConsentErr').hidden=true;$('d11SaveErr').hidden=true;
  $('d11Email').removeAttribute('aria-invalid');$('d11ConsentRow').removeAttribute('data-error');
  if(!$('d11Email').value)$('d11Email').value=lsGet(K_EMAIL,'')||'';
  setBusy(false);
  $('d11Discard').textContent=playsLeft()>0?'唔儲存，再玩一次':'唔儲存，返回';   // always there
}
function setBusy(on){var b=$('d11Submit');b.disabled=on;b.textContent=on?'儲存中…':'提交並取得成績紀錄編號'}
function validate(){
  /* brief p2: trim accidental spaces, inline error for missing or invalid */
  var raw=$('d11Email').value,email=raw.trim().toLowerCase();
  if(raw!==raw.trim())$('d11Email').value=raw.trim();
  var err=!email?'請輸入電郵地址。':!EMAIL_RE.test(email)?'電郵地址格式不正確，請再檢查。':'';
  $('d11EmailErr').textContent=err;$('d11EmailErr').hidden=!err;
  if(err)$('d11Email').setAttribute('aria-invalid','true');else $('d11Email').removeAttribute('aria-invalid');
  var consent=$('d11Consent').checked;
  $('d11ConsentErr').hidden=consent;
  if(consent)$('d11ConsentRow').removeAttribute('data-error');else $('d11ConsentRow').setAttribute('data-error','1');
  if(err){$('d11Email').focus();return null}
  if(!consent)return null;
  return email;
}
function buildPayload(r){
  /* brief p2 "Data for internal ranking and matching" — one row per
     submitted round. form.io stamps its own server `created` time on the
     row: that is the submission timestamp to rank and tie-break on.
     client_submitted_at is kept for reference only. */
  return {
    email: r.email,
    result_code: r.result_code,
    session_id: r.session_id,
    score: r.score,
    good_taps: r.good,
    bad_taps: r.bad,
    max_combo: r.max_combo,   // tie-break after score (Marketing 2026-10-26); needs the form.io field max_combo
    completed_at: r.completed_at,
    client_submitted_at: new Date().toISOString(),
    game_version: CFG.GAME_VERSION,
    consent_pics: true,
    taps_log: r.log,
    rubbish_shown: r.rubbish,
    play_no: r.play_no,
    campaign: CFG.CAMPAIGN
  };
}
var REQUIRED_KEYS=Object.keys(buildPayload({}));

function postSubmission(data){
  
  if(!FORM_URL)return Promise.reject(new Error('form.io URL not set (window.MH_D11_FORM_URL)'));
  var ctl=window.AbortController?new AbortController():null,timer=setTimeout(function(){if(ctl)ctl.abort()},15000);
  return fetch(FORM_URL+'/submission',{method:'POST',credentials:'omit',headers:{'Content-Type':'application/json'},body:JSON.stringify({data:data}),signal:ctl?ctl.signal:undefined})
    .then(function(res){return res.text().then(function(t){var body=null;try{body=JSON.parse(t)}catch(e){}clearTimeout(timer);return {ok:res.ok,status:res.status,body:body}})},function(e){clearTimeout(timer);throw e});
}
/* A retry after a lost response must not create a second row (brief p2
   "Submission retries produce no duplicates"). session_id is marked Unique
   on the form, so the second POST is refused with a unique error, which
   here means "the first one landed". */
function isUniqueClash(body,key){
  var ds=(body&&body.details)||[];
  return ds.some(function(d){var p=d.path||[],v=d.context&&d.context.validator;return p.indexOf(key)>-1&&(v==='unique'||/unique/i.test(d.message||''))});
}
function saveRound(r){
  return postSubmission(buildPayload(r)).then(function(res){
    if(res.ok){
      /* Only show a code form.io has actually stored. If a component is
         missing, form.io silently drops that value — the echo catches it. */
      var d=res.body&&res.body.data;
      if(!d||d.result_code!==r.result_code||d.session_id!==r.session_id)throw new Error('form.io did not store result_code / session_id — check the form components');
      return;
    }
    if(res.status===400&&isUniqueClash(res.body,'session_id'))return;
    throw new Error('form.io '+res.status+' '+((res.body&&res.body.message)||''));
  });
}
function onSubmit(ev){
  ev.preventDefault();
  if(saving||mode!=='result')return;
  $('d11SaveErr').hidden=true;
  var email=validate();if(!email)return;
  round.email=email;
  if(!round.result_code)round.result_code=newResultCode();
  saving=true;setBusy(true);
  saveRound(round).then(function(){
    saving=false;mode='saved';
    lsSet(K_EMAIL,email);
    var list=lsGet(K_SAVED,[]);if(!Array.isArray(list))list=[];
    list.push({code:round.result_code,score:round.score,at:round.completed_at});lsSet(K_SAVED,list);
    gaFormSubmit(round);   // form_submit fires only once form.io has confirmed the save
    showSaved();
  },function(err){
    saving=false;setBusy(false);
    console.error('[d11-game] save failed:',err&&err.message);
    $('d11SaveErr').textContent='未能儲存成績，請檢查網絡後再試一次。你嘅分數仍然保留喺度。';
    $('d11SaveErr').hidden=false;
  });
}
function showSaved(){
  $('savedScore').textContent=round.score;
  $('savedEmail').textContent=round.email;
  $('savedCode').textContent=round.result_code;
  $('copyButton').textContent='複製成績紀錄編號';
  var left=playsLeft();
  $('replayButton').hidden=left<=0;
  $('savedLeft').textContent=left===Infinity?'唔滿意？再玩一次，揀最高分嗰個編號提交。':left>0?'你仲有 '+left+' 次挑戰機會。':'你已完成 '+CFG.MAX_PLAYS+' 次挑戰。';
  refreshCodeCount();
  showOnly('savedOverlay');
}
/* "我的成績紀錄編號" — every code saved on this device, best score first (Marketing 2026-10-23:
   unlimited plays, the player picks one code for the reward form). from = card to return to. */
var codesFrom='start';
function savedList(){var l=lsGet(K_SAVED,[]);return Array.isArray(l)?l:[]}
function refreshCodeCount(){var n=savedList().length;__root.querySelectorAll('[data-codes]').forEach(function(e){e.textContent=n});var b=$('codesOpen1');if(b)b.hidden=!n}
function showCodes(from){
  codesFrom=from||'start';
  var ul=$('limitCodes'),list=savedList().slice().sort(function(a,b){return b.score-a.score});ul.replaceChildren();
  if(!list.length){var li=document.createElement('li');li.className='d11-codes__empty';li.textContent='呢部裝置未有儲存成績。';ul.append(li)}
  else list.forEach(function(it,i){
    var li=document.createElement('li'),c=document.createElement('span'),s=document.createElement('span'),b=document.createElement('button');
    c.className='d11-codes__code';c.textContent=it.code;s.className='d11-codes__score';s.textContent=it.score+' 分'+(i===0?' · 最高分':'');
    b.type='button';b.className='mhg-btn mhg-btn--outline-primary mhg-btn--small';b.textContent='複製';
    b.addEventListener('click',function(){copyText(it.code,b,'複製')});
    li.append(c,s,b);ul.append(li);
  });
  showOnly('limitOverlay');
}
function copyText(text,btn,label){
  function done(ok){btn.textContent=ok?'已複製':label;if(ok)setTimeout(function(){btn.textContent=label},1700)}
  if(navigator.clipboard&&navigator.clipboard.writeText){navigator.clipboard.writeText(text).then(function(){done(true)},function(){fallback()});return}
  fallback();
  function fallback(){
    var ta=document.createElement('textarea');ta.value=text;ta.setAttribute('readonly','');ta.style.position='fixed';ta.style.opacity='0';__root.append(ta);ta.select();
    var ok=false;try{ok=document.execCommand('copy')}catch(e){}ta.remove();
    if(!ok){var r=document.createRange();r.selectNodeContents($('savedCode'));var sel=getSelection();sel.removeAllRanges();sel.addRange(r)}
    done(ok);
  }
}

/* ── form.io schema check (non-blocking) — same idea as the tax quiz:
   a missing component means a silently dropped value and a missing CSV
   column, so name it in the console the moment the page loads. */
function checkSchema(){
  if(!FORM_URL){console.error('[d11-game] window.MH_D11_FORM_URL is not set — results cannot be saved');return}
  fetch(FORM_URL,{credentials:'omit'}).then(function(r){return r.json()}).then(function(def){
    var keys=[];(function walk(cs){(cs||[]).forEach(function(c){if(c.key)keys.push(c.key);if(c.components)walk(c.components);if(c.columns)c.columns.forEach(function(col){walk(col.components)})})})(def.components);
    var missing=REQUIRED_KEYS.filter(function(k){return keys.indexOf(k)===-1});
    if(missing.length)console.error('[d11-game] form.io is missing '+missing.length+' component(s): '+missing.join(', '));
  }).catch(function(){console.error('[d11-game] form.io schema unreachable: '+FORM_URL)});
}

/* ── CAMPAIGN COUNTDOWN (Clara, 2026-10-16) ─────────────────────────
   Fixed HKT instants, so every visitor counts to the same moment
   whatever their device's time zone. */
var clockNow=function(){return Date.now()};

var T_START=Date.parse(CFG.START),T_END=Date.parse(CFG.END),cdTimer=null;
function pad2(n){return (n<10?'0':'')+n}
function renderCountdown(){
  var now=clockNow(),target,label;
  if(now<T_START){target=T_START;label='距離活動開始仲有'}
  else if(now<T_END){target=T_END;label='距離活動結束仲有'}
  else{$('d11CdLabel').textContent='活動已經結束，多謝參與！';$('d11CdUnits').hidden=true;if(cdTimer){clearInterval(cdTimer);cdTimer=null}return}
  var s=Math.max(0,Math.floor((target-now)/1000));
  $('d11CdLabel').textContent=label;$('d11CdUnits').hidden=false;
  $('d11CdD').textContent=pad2(Math.floor(s/86400));$('d11CdH').textContent=pad2(Math.floor(s%86400/3600));
  $('d11CdM').textContent=pad2(Math.floor(s%3600/60));$('d11CdS').textContent=pad2(s%60);
}
renderCountdown();cdTimer=setInterval(renderCountdown,1000);

/* ── SECTION TABS (deck design only; the V3 design has none) ────────
   Clicks scroll in place (no hash jump); the game tab centres the whole
   play area, like start(). The underline follows the section in view. */
(function(){
  var nav=__root.querySelector('.dk-tabs');if(!nav)return;
  var row=nav.querySelector('.dk-tabs__in'),links=[].slice.call(nav.querySelectorAll('a[href^="#"]'));
  var targets=links.map(function(a){return __root.querySelector(a.getAttribute('href'))});
  var cur=-1,lockUntil=0,lockTimer=null;
  function setCurrent(i){
    if(i===cur)return;cur=i;
    links.forEach(function(a,k){if(k===i)a.setAttribute('aria-current','true');else a.removeAttribute('aria-current')});
    var a=links[i];if(a&&row.scrollWidth>row.clientWidth){if(a.offsetLeft<row.scrollLeft||a.offsetLeft+a.offsetWidth>row.scrollLeft+row.clientWidth)row.scrollLeft=Math.max(0,a.offsetLeft-16)}
  }
  function update(){
    /* a clicked tab stays current while its smooth scroll runs: near the page end a
       section cannot scroll up to the bar, and would otherwise hand the underline on */
    if(Date.now()<lockUntil){clearTimeout(lockTimer);lockTimer=setTimeout(function(){lockUntil=0},160);lockUntil=Date.now()+1500;return}
    /* the bar's stuck position, not where it sits in the flow before it sticks */
    var top=parseFloat(getComputedStyle(nav).top)||0,line=top+nav.offsetHeight+24,i=0;
    targets.forEach(function(t,k){if(t&&t.getBoundingClientRect().top<=line)i=k});
    setCurrent(i);
  }
  links.forEach(function(a,k){a.addEventListener('click',function(ev){
    var t=targets[k];if(!t)return;ev.preventDefault();
    if(t.contains($('screen'))){bringIntoView();}
    else{try{t.scrollIntoView({behavior:'smooth',block:'start'})}catch(e){t.scrollIntoView()}}
    setCurrent(k);lockUntil=Date.now()+1500;
  })});
  window.addEventListener('scroll',update,{passive:true});window.addEventListener('resize',update);update();
})();

